-- =====================================================================================
-- TÜRK ORBIT — Migration 0006: Görev sistemi (Aşama 10)
--
--  * Görevler: ana ve zincir görevler (main), günlük (daily), haftalık (weekly), etkinlik (event).
--  * Hedefler yalnızca BUGÜN ilerleyebilen olay türlerini kullanır (oyun sunucusu ve hangar olayları).
--    Maden (collect_resource) ve Yıldız Kapısı (complete_gate) hedefleri o sistemler gelince eklenecek.
--  * İlerleme yalnızca sunucu tarafında yazılır; istemcinin ilerleme yazabileceği bir uç yoktur.
--  * Günlük/haftalık görevler kişiye özel, tohumlu rastgele seçilir; sıfırlama 05:00 TSİ (cycle_key).
--  * Ödül, görev tamamlanınca "Ödülü al" ile verilir (defterli, idempotent anahtar).
--  Tüm görevler Yönetim Merkezi'nden (Aşama 14) düzenlenebilecek şekilde veritabanındadır.
-- =====================================================================================

CREATE TABLE quests (
  id                    serial PRIMARY KEY,
  code                  text NOT NULL UNIQUE,
  category              text NOT NULL CHECK (category IN ('main', 'daily', 'weekly', 'event')),
  title                 text NOT NULL,
  description           text NOT NULL,
  min_level             smallint NOT NULL DEFAULT 1 CHECK (min_level BETWEEN 1 AND 50),
  -- günlük/haftalık havuzda seviye bandının üst sınırı (NULL = sınır yok)
  max_level             smallint CHECK (max_level IS NULL OR max_level >= min_level),
  prerequisite_quest_id integer REFERENCES quests(id),   -- zincir: önceki görevin ödülü alınmış olmalı
  chain_code            text,
  chain_order           smallint,
  reward_table_id       integer NOT NULL REFERENCES reward_tables(id),
  starts_at             timestamptz,
  ends_at               timestamptz,
  sort_order            integer NOT NULL DEFAULT 0,
  is_published          boolean NOT NULL DEFAULT true,
  created_at            timestamptz NOT NULL DEFAULT now(),
  CHECK (category <> 'event' OR (starts_at IS NOT NULL AND ends_at IS NOT NULL)),
  CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at),
  CHECK (prerequisite_quest_id IS NULL OR prerequisite_quest_id <> id)
);
CREATE INDEX quests_category_idx ON quests(category, is_published);

CREATE TABLE quest_objectives (
  id             serial PRIMARY KEY,
  quest_id       integer NOT NULL REFERENCES quests(id) ON DELETE CASCADE,
  sort_order     smallint NOT NULL,
  objective_type text NOT NULL CHECK (objective_type IN (
                   'kill_npc', 'kill_player', 'collect_cargo', 'visit_map', 'deal_damage', 'travel_distance',
                   'fire_rockets', 'jump_portal', 'upgrade_item', 'buy_item', 'reach_level')),
  -- {"npc":["cakal"],"family":["akrep"],"maps":["{c}-2"],"map_types":["border"],"target":"npc","min_level":3,"category":["ammo"]}
  -- "{c}" pilotun şirket harf önekiyle değiştirilir (K, G, A).
  params         jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(params) = 'object'),
  target         bigint NOT NULL CHECK (target > 0),
  label          text NOT NULL,
  UNIQUE (quest_id, sort_order)
);

CREATE TABLE player_quests (
  id           bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  player_id    uuid NOT NULL REFERENCES players(id) ON DELETE CASCADE,
  quest_id     integer NOT NULL REFERENCES quests(id),
  -- 'once' (ana/etkinlik) · günlük: '2026-11-28' · haftalık: '2026-W48' (05:00 TSİ sıfırlama)
  cycle_key    text NOT NULL DEFAULT 'once',
  status       text NOT NULL CHECK (status IN ('active', 'completed', 'claimed', 'rerolled', 'abandoned')),
  -- {"<objective_id>": ilerleme}; yalnızca sunucu yazar, hedefi aşamaz
  progress     jsonb NOT NULL DEFAULT '{}'::jsonb,
  accepted_at  timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  claimed_at   timestamptz,
  UNIQUE (player_id, quest_id, cycle_key),
  CHECK (status NOT IN ('completed', 'claimed') OR completed_at IS NOT NULL),
  CHECK (status <> 'claimed' OR claimed_at IS NOT NULL)
);
CREATE INDEX player_quests_active_idx ON player_quests(player_id, status);

-- Günlük/haftalık atama ve yeniden çekme hakkı (döngü başına bir satır)
CREATE TABLE player_quest_cycles (
  player_id    uuid NOT NULL REFERENCES players(id) ON DELETE CASCADE,
  category     text NOT NULL CHECK (category IN ('daily', 'weekly')),
  cycle_key    text NOT NULL,
  rerolls_used smallint NOT NULL DEFAULT 0 CHECK (rerolls_used >= 0),
  assigned_at  timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (player_id, category, cycle_key)
);

  -- Görev kuralları. Sıfırlama saati Türkiye saatiyle (UTC+3).
  ('quests', '{"daily_count": 3, "weekly_count": 3, "daily_rerolls": 1, "weekly_rerolls": 1, "reset_hour_tr": 5,
               "max_active": 10, "kill_credit_min_share": 0.2}'::jsonb)
ON CONFLICT (key) DO NOTHING;

